    public Object parseOrder(Object order, Map<String, Object> market)
    {
        //
        //     {
        //         "currency_pair": "btc_jpy",
        //         "action": "ask",
        //         "amount": 0.03,
        //         "price": 56000,
        //         "timestamp": 1402021125,
        //         "comment" : "demo"
        //     }
        //
        // cancelOrder
        //
        //    {
        //        "order_id": 184,
        //        "funds": {
        //            "jpy": 15320,
        //            "btc": 1.392,
        //            "mona": 2600,
        //            "kaori": 0.1
        //        }
        //    }
        //
        String side = this.safeString(order, "action");
        side = (((java.util.Objects.equals(side, "bid")))) ? "buy" : "sell";
        Long timestamp = this.safeTimestamp(order, "timestamp");
        String marketId = this.safeString(order, "currency_pair");
        String symbol = this.safeSymbol(marketId, market, "_", (String) null);
        String price = this.safeString(order, "price");
        String amount = this.safeString(order, "amount");
        String id = this.safeString2(order, "id", "order_id");
        return this.safeOrder(Helpers.newMap(
            "id", id,
            "clientOrderId", null,
            "timestamp", timestamp,
            "datetime", this.iso8601(timestamp),
            "lastTradeTimestamp", null,
            "status", "open",
            "symbol", symbol,
            "type", "limit",
            "timeInForce", null,
            "postOnly", null,
            "side", side,
            "price", price,
            "triggerPrice", null,
            "cost", null,
            "amount", amount,
            "filled", null,
            "remaining", null,
            "trades", null,
            "fee", null,
            "info", order,
            "average", null
        ), market);
    }

